"""Business logic for the loopback OAuth service, independent of HTTP transport.

Each public method takes an already-JSON-decoded payload (whatever value the
request body decoded to) and returns a (status_code, body_dict) pair. Keeping
this logic separate from the HTTP layer makes it directly testable and keeps
the token-response shape defined in exactly one place.
"""

from __future__ import annotations

import json
import time
import urllib.parse
from typing import Any

from . import grants, security
from .db import Database

AUTH_CODE_TTL_SECONDS = 60
LOGIN_TTL_SECONDS = 600

MALFORMED_REQUEST = (400, {"error": "malformed_request"})
NOT_FOUND = (404, {"error": "not_found"})


def _fields(payload: Any, required: set[str]) -> dict[str, str] | None:
    """Return the payload as a dict if it has exactly the required string fields."""
    if not isinstance(payload, dict):
        return None
    if set(payload.keys()) != required:
        return None
    for value in payload.values():
        if not isinstance(value, str):
            return None
    return payload


class OAuthService:
    def __init__(self, db: Database, signing_key: str):
        self._db = db
        self._secret = signing_key.encode("utf-8")

    # -- /oauth/authorize -------------------------------------------------

    def authorize(self, payload: Any) -> tuple[int, dict]:
        fields = _fields(payload, {"client_id", "redirect_uri", "state"})
        if fields is None:
            return MALFORMED_REQUEST

        client_id = fields["client_id"]
        redirect_uri = fields["redirect_uri"]
        state = fields["state"]

        client = self._db.get_client(client_id)
        if client is None or client["redirect_uri"] != redirect_uri:
            return 400, {"error": "unregistered_callback"}

        login_id = security.new_opaque_id()
        self._db.create_pending_login(login_id, client_id, redirect_uri, state, kind="login")

        return 201, {
            "login_id": login_id,
            "resume_reference": _resume_reference("login", client_id, login_id),
        }

    # -- /login/complete ----------------------------------------------------

    def login_complete(self, payload: Any) -> tuple[int, dict]:
        fields = _fields(payload, {"login_id", "account_id", "password"})
        if fields is None:
            return MALFORMED_REQUEST

        login_id = fields["login_id"]
        account_id = fields["account_id"]
        password = fields["password"]

        pending = self._db.get_pending_login(login_id)
        if pending is None:
            return 403, {"error": "invalid_login"}

        expired = (time.time() - pending["created_at"]) > LOGIN_TTL_SECONDS
        already_resolved = pending["status"] != "pending"

        if pending["kind"] == "continuation":
            if expired or already_resolved:
                return 403, {"error": "invalid_continuation"}
        else:
            if expired:
                return 403, {"error": "invalid_login"}
            if already_resolved:
                return 403, {"error": "invalid_authorization"}

        account = self._db.get_account(account_id)
        if account is None or not security.verify_password(
            password, account["salt"], account["password_hash"]
        ):
            return 403, {"error": "invalid_credentials"}

        code = security.new_opaque_id()
        self._db.create_auth_code(code, pending["client_id"], account_id)
        self._db.mark_login_completed(login_id)

        location = _append_query(pending["redirect_uri"], code=code, state=pending["state"])
        return 200, {"location": location}

    # -- /oauth/token -------------------------------------------------------

    def token(self, payload: Any) -> tuple[int, dict]:
        if isinstance(payload, dict) and "code" in payload:
            return self._token_from_code(payload)
        if isinstance(payload, dict) and "refresh_token" in payload:
            return self._token_from_refresh(payload)
        return MALFORMED_REQUEST

    def _token_from_code(self, payload: Any) -> tuple[int, dict]:
        fields = _fields(payload, {"client_id", "code"})
        if fields is None:
            return MALFORMED_REQUEST

        client_id = fields["client_id"]
        code = fields["code"]

        record = self._db.get_auth_code(code)
        if (
            record is None
            or record["used"]
            or (time.time() - record["created_at"]) > AUTH_CODE_TTL_SECONDS
        ):
            return 403, {"error": "invalid_code"}

        if record["client_id"] != client_id:
            return 403, {"error": "wrong_client"}

        self._db.mark_auth_code_used(code)
        return 200, self._issue_tokens(client_id, record["account_id"])

    def _token_from_refresh(self, payload: Any) -> tuple[int, dict]:
        fields = _fields(payload, {"client_id", "refresh_token"})
        if fields is None:
            return MALFORMED_REQUEST

        client_id = fields["client_id"]
        refresh_token = fields["refresh_token"]

        if not security.verify(refresh_token, self._secret):
            return 403, {"error": "invalid_refresh_token"}

        record = self._db.get_refresh_token(refresh_token)
        if record is None or record["revoked"]:
            return 403, {"error": "invalid_refresh_token"}

        if record["client_id"] != client_id:
            return 403, {"error": "wrong_client"}

        self._db.revoke_refresh_token(refresh_token)
        self._db.append_grant_decision(refresh_token, _rotated_decision())
        return 200, self._issue_tokens(client_id, record["account_id"])

    # -- /oauth/grant/status ------------------------------------------------

    def grant_status(self, payload: Any) -> tuple[int, dict]:
        fields = _fields(payload, {"client_id", "refresh_token"})
        if fields is None:
            return MALFORMED_REQUEST

        client_id = fields["client_id"]
        refresh_token = fields["refresh_token"]

        record = self._db.get_refresh_grant(refresh_token)
        if record is None:
            return NOT_FOUND

        if record["client_id"] != client_id:
            return 403, {"error": "wrong_client"}

        grant = {
            "current_decision": json.loads(record["current_decision"]),
            "decision_history": json.loads(record["decision_history"]),
        }
        return 200, {
            "client_id": record["client_id"],
            "account_id": record["account_id"],
            "decision": grants.effective_decision(grant),
        }

    # -- /oauth/grant/revoke ------------------------------------------------

    def revoke_grant(self, payload: Any) -> tuple[int, dict]:
        fields = _fields(payload, {"client_id", "refresh_token"})
        if fields is None:
            return MALFORMED_REQUEST

        client_id = fields["client_id"]
        refresh_token = fields["refresh_token"]

        record = self._db.get_refresh_grant(refresh_token)
        if record is None:
            return NOT_FOUND

        if record["client_id"] != client_id:
            return 403, {"error": "wrong_client"}

        self._db.revoke_refresh_token(refresh_token)
        self._db.append_grant_decision(refresh_token, _revoked_decision())

        return self.grant_status(payload)

    def _issue_tokens(self, client_id: str, account_id: str) -> dict:
        """Mint a fresh access/refresh token pair and format the token response.

        This is the common formatting shared by every /oauth/token success
        branch, so the wire shape is defined exactly once.
        """
        access_token = security.new_opaque_id()
        refresh_token = security.sign(self._secret)
        self._db.create_refresh_token(refresh_token, client_id, account_id)
        self._db.create_refresh_grant(refresh_token, client_id, account_id, _active_decision())
        return format_token_response(
            access_token=access_token,
            refresh_token=refresh_token,
            client_id=client_id,
            account_id=account_id,
        )


def format_token_response(
    *, access_token: str, refresh_token: str, client_id: str, account_id: str
) -> dict:
    """The single place that defines the /oauth/token success response shape."""
    return {
        "access_token": access_token,
        "refresh_token": refresh_token,
        "client_id": client_id,
        "account_id": account_id,
    }


def _active_decision() -> dict:
    """The decision recorded when a refresh grant is first created."""
    return {"decision": "active", "at": time.time()}


def _rotated_decision() -> dict:
    """The decision recorded on a grant whose refresh token was exchanged for a new one."""
    return {"decision": "rotated", "at": time.time()}


def _revoked_decision() -> dict:
    """The decision recorded on a grant revoked before its refresh token was exchanged."""
    return {"decision": "revoked", "at": time.time()}


def _resume_reference(kind: str, client_id: str, login_id: str) -> dict:
    return {"kind": kind, "client_id": client_id, "value": login_id}


def _append_query(uri: str, **params: str) -> str:
    parts = urllib.parse.urlsplit(uri)
    query = urllib.parse.parse_qsl(parts.query, keep_blank_values=True)
    query.extend(params.items())
    new_query = urllib.parse.urlencode(query)
    return urllib.parse.urlunsplit(
        (parts.scheme, parts.netloc, parts.path, new_query, parts.fragment)
    )

"""SQLite-backed durable storage for accounts, clients, and login state."""

from __future__ import annotations

import json
import sqlite3
import time
from typing import Optional

_SCHEMA = """
CREATE TABLE IF NOT EXISTS accounts (
    account_id TEXT PRIMARY KEY,
    email TEXT NOT NULL,
    salt TEXT NOT NULL,
    password_hash TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS clients (
    client_id TEXT PRIMARY KEY,
    redirect_uri TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS pending_logins (
    login_id TEXT PRIMARY KEY,
    client_id TEXT NOT NULL,
    redirect_uri TEXT NOT NULL,
    state TEXT NOT NULL,
    kind TEXT NOT NULL,
    status TEXT NOT NULL,
    created_at REAL NOT NULL
);

CREATE TABLE IF NOT EXISTS legacy_logins (
    client_id TEXT NOT NULL,
    legacy_handle TEXT NOT NULL,
    login_id TEXT NOT NULL,
    recovery_locator TEXT NOT NULL,
    PRIMARY KEY (client_id, legacy_handle)
);

CREATE TABLE IF NOT EXISTS auth_codes (
    code TEXT PRIMARY KEY,
    client_id TEXT NOT NULL,
    account_id TEXT NOT NULL,
    created_at REAL NOT NULL,
    used INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS refresh_tokens (
    token TEXT PRIMARY KEY,
    client_id TEXT NOT NULL,
    account_id TEXT NOT NULL,
    created_at REAL NOT NULL,
    revoked INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS refresh_grants (
    token TEXT PRIMARY KEY,
    client_id TEXT NOT NULL,
    account_id TEXT NOT NULL,
    current_decision TEXT NOT NULL,
    decision_history TEXT NOT NULL,
    created_at REAL NOT NULL
);
"""


class Database:
    def __init__(self, path: str):
        self._conn = sqlite3.connect(path, check_same_thread=False)
        self._conn.row_factory = sqlite3.Row
        self._conn.executescript(_SCHEMA)
        self._conn.commit()

    def close(self) -> None:
        self._conn.close()

    # -- accounts ---------------------------------------------------

    def create_account(self, account_id: str, email: str, salt_hex: str, hash_hex: str) -> None:
        try:
            self._conn.execute(
                "INSERT INTO accounts (account_id, email, salt, password_hash) VALUES (?, ?, ?, ?)",
                (account_id, email, salt_hex, hash_hex),
            )
            self._conn.commit()
        except sqlite3.IntegrityError as exc:
            raise ValueError(f"account already exists: {account_id}") from exc

    def get_account(self, account_id: str) -> Optional[sqlite3.Row]:
        return self._conn.execute(
            "SELECT * FROM accounts WHERE account_id = ?", (account_id,)
        ).fetchone()

    # -- clients ------------------------------------------------------

    def register_client(self, client_id: str, redirect_uri: str) -> None:
        try:
            self._conn.execute(
                "INSERT INTO clients (client_id, redirect_uri) VALUES (?, ?)",
                (client_id, redirect_uri),
            )
            self._conn.commit()
        except sqlite3.IntegrityError as exc:
            raise ValueError(f"client already exists: {client_id}") from exc

    def get_client(self, client_id: str) -> Optional[sqlite3.Row]:
        return self._conn.execute(
            "SELECT * FROM clients WHERE client_id = ?", (client_id,)
        ).fetchone()

    # -- pending logins -------------------------------------------------

    def create_pending_login(
        self, login_id: str, client_id: str, redirect_uri: str, state: str, kind: str
    ) -> None:
        self._conn.execute(
            "INSERT INTO pending_logins "
            "(login_id, client_id, redirect_uri, state, kind, status, created_at) "
            "VALUES (?, ?, ?, ?, ?, 'pending', ?)",
            (login_id, client_id, redirect_uri, state, kind, time.time()),
        )
        self._conn.commit()

    def get_pending_login(self, login_id: str) -> Optional[sqlite3.Row]:
        return self._conn.execute(
            "SELECT * FROM pending_logins WHERE login_id = ?", (login_id,)
        ).fetchone()

    def mark_login_completed(self, login_id: str) -> None:
        self._conn.execute(
            "UPDATE pending_logins SET status = 'completed' WHERE login_id = ?", (login_id,)
        )
        self._conn.commit()

    # -- legacy import ----------------------------------------------------

    def import_legacy_login(
        self,
        client_id: str,
        legacy_handle: str,
        login_id: str,
        recovery_locator: str,
    ) -> None:
        try:
            self._conn.execute(
                "INSERT INTO legacy_logins (client_id, legacy_handle, login_id, recovery_locator) "
                "VALUES (?, ?, ?, ?)",
                (client_id, legacy_handle, login_id, recovery_locator),
            )
            self._conn.commit()
        except sqlite3.IntegrityError as exc:
            raise ValueError(
                f"legacy handle already imported for client: {client_id}/{legacy_handle}"
            ) from exc

    # -- authorization codes ------------------------------------------

    def create_auth_code(self, code: str, client_id: str, account_id: str) -> None:
        self._conn.execute(
            "INSERT INTO auth_codes (code, client_id, account_id, created_at, used) "
            "VALUES (?, ?, ?, ?, 0)",
            (code, client_id, account_id, time.time()),
        )
        self._conn.commit()

    def get_auth_code(self, code: str) -> Optional[sqlite3.Row]:
        return self._conn.execute("SELECT * FROM auth_codes WHERE code = ?", (code,)).fetchone()

    def mark_auth_code_used(self, code: str) -> None:
        self._conn.execute("UPDATE auth_codes SET used = 1 WHERE code = ?", (code,))
        self._conn.commit()

    # -- refresh tokens -------------------------------------------------

    def create_refresh_token(self, token: str, client_id: str, account_id: str) -> None:
        self._conn.execute(
            "INSERT INTO refresh_tokens (token, client_id, account_id, created_at, revoked) "
            "VALUES (?, ?, ?, ?, 0)",
            (token, client_id, account_id, time.time()),
        )
        self._conn.commit()

    def get_refresh_token(self, token: str) -> Optional[sqlite3.Row]:
        return self._conn.execute(
            "SELECT * FROM refresh_tokens WHERE token = ?", (token,)
        ).fetchone()

    def revoke_refresh_token(self, token: str) -> None:
        self._conn.execute("UPDATE refresh_tokens SET revoked = 1 WHERE token = ?", (token,))
        self._conn.commit()

    # -- refresh grants ---------------------------------------------------

    def create_refresh_grant(
        self, token: str, client_id: str, account_id: str, decision: dict
    ) -> None:
        """Create a grant with `decision` as both its current decision and the sole entry of its append-only decision history."""
        self._conn.execute(
            "INSERT INTO refresh_grants "
            "(token, client_id, account_id, current_decision, decision_history, created_at) "
            "VALUES (?, ?, ?, ?, ?, ?)",
            (
                token,
                client_id,
                account_id,
                json.dumps(decision),
                json.dumps([decision]),
                time.time(),
            ),
        )
        self._conn.commit()

    def get_refresh_grant(self, token: str) -> Optional[sqlite3.Row]:
        return self._conn.execute(
            "SELECT * FROM refresh_grants WHERE token = ?", (token,)
        ).fetchone()

    def append_grant_decision(self, token: str, decision: dict) -> None:
        """Append `decision` to the grant's history and make it the current decision."""
        record = self.get_refresh_grant(token)
        history = json.loads(record["decision_history"])
        history.append(decision)
        self._conn.execute(
            "UPDATE refresh_grants SET current_decision = ?, decision_history = ? WHERE token = ?",
            (json.dumps(decision), json.dumps(history), token),
        )
        self._conn.commit()

"""Focused tests for oauthsvc.grants.effective_decision."""

from __future__ import annotations

import unittest

from oauthsvc.grants import effective_decision


class TestEffectiveDecision(unittest.TestCase):
    def test_returns_current_decision_when_present(self):
        grant = {
            "current_decision": {"decision": "approved", "at": "2026-01-01T00:00:00Z"},
            "decision_history": [
                {"decision": "pending", "at": "2025-12-31T00:00:00Z"},
                {"decision": "approved", "at": "2026-01-01T00:00:00Z"},
            ],
        }
        self.assertEqual(
            effective_decision(grant), {"decision": "approved", "at": "2026-01-01T00:00:00Z"}
        )

    def test_falls_back_to_latest_history_entry_when_current_decision_is_empty(self):
        grant = {
            "current_decision": None,
            "decision_history": [
                {"decision": "pending", "at": "2025-12-31T00:00:00Z"},
                {"decision": "approved", "at": "2026-01-01T00:00:00Z"},
            ],
        }
        self.assertEqual(
            effective_decision(grant), {"decision": "approved", "at": "2026-01-01T00:00:00Z"}
        )

    def test_falls_back_when_current_decision_field_is_missing_entirely(self):
        grant = {
            "decision_history": [
                {"decision": "revoked", "at": "2024-06-15T00:00:00Z"},
            ],
        }
        self.assertEqual(
            effective_decision(grant), {"decision": "revoked", "at": "2024-06-15T00:00:00Z"}
        )


if __name__ == "__main__":
    unittest.main()

"""Read-only summary tool for the sample listings under examples/.

Reads the JSON Lines files under examples/ and prints, for each file and for
all files combined: listing counts by category, by status, and by launch
year, plus the ten owning teams with the most listings.

Standard library only. Reads only files under examples/ (matched by
--file or, by default, every "*.jsonl" file there); it does not import the
oauthsvc package or open any database.
"""

from __future__ import annotations

import argparse
import json
import sys
from collections import Counter
from pathlib import Path
from typing import Any

EXAMPLES_DIR = Path(__file__).resolve().parent.parent / "examples"

TOP_TEAMS_LIMIT = 10


def load_listings(path: Path) -> list[dict[str, Any]]:
    listings = []
    with path.open("r", encoding="utf-8") as f:
        for line_no, line in enumerate(f, start=1):
            line = line.strip()
            if not line:
                continue
            try:
                listings.append(json.loads(line))
            except json.JSONDecodeError as exc:
                raise ValueError(f"{path.name}: invalid JSON on line {line_no}: {exc}") from exc
    return listings


def summarize(listings: list[dict[str, Any]]) -> dict[str, Any]:
    by_category: Counter[str] = Counter()
    by_status: Counter[str] = Counter()
    by_launch_year: Counter[str] = Counter()
    by_team: Counter[str] = Counter()

    for listing in listings:
        by_category[listing.get("category", "unknown")] += 1
        by_status[listing.get("status", "unknown")] += 1
        launch_date = listing.get("launch_date", "")
        year = launch_date.split("-")[0] if launch_date else "unknown"
        by_launch_year[year] += 1
        by_team[listing.get("owning_team", "unknown")] += 1

    return {
        "total_listings": len(listings),
        "by_category": dict(sorted(by_category.items(), key=lambda kv: (-kv[1], kv[0]))),
        "by_status": dict(sorted(by_status.items(), key=lambda kv: (-kv[1], kv[0]))),
        "by_launch_year": dict(sorted(by_launch_year.items(), key=lambda kv: kv[0])),
        "top_owning_teams": [
            {"owning_team": team, "count": count}
            for team, count in by_team.most_common(TOP_TEAMS_LIMIT)
        ],
    }


def print_summary(title: str, summary: dict[str, Any]) -> None:
    print(f"== {title} ==")
    print(f"Total listings: {summary['total_listings']}")

    print("By category:")
    for category, count in summary["by_category"].items():
        print(f"  {category}: {count}")

    print("By status:")
    for status, count in summary["by_status"].items():
        print(f"  {status}: {count}")

    print("By launch year:")
    for year, count in summary["by_launch_year"].items():
        print(f"  {year}: {count}")

    print(f"Top {TOP_TEAMS_LIMIT} owning teams:")
    for entry in summary["top_owning_teams"]:
        print(f"  {entry['owning_team']}: {entry['count']}")

    print()


def merge_counters(summaries: list[dict[str, Any]], key: str) -> Counter:
    merged: Counter = Counter()
    for summary in summaries:
        merged.update(summary[key])
    return merged


def combine(summaries: list[dict[str, Any]]) -> dict[str, Any]:
    total = sum(s["total_listings"] for s in summaries)
    by_category = merge_counters(summaries, "by_category")
    by_status = merge_counters(summaries, "by_status")
    by_launch_year = merge_counters(summaries, "by_launch_year")

    by_team: Counter[str] = Counter()
    for summary in summaries:
        for entry in summary["top_owning_teams"]:
            by_team[entry["owning_team"]] += entry["count"]

    return {
        "total_listings": total,
        "by_category": dict(sorted(by_category.items(), key=lambda kv: (-kv[1], kv[0]))),
        "by_status": dict(sorted(by_status.items(), key=lambda kv: (-kv[1], kv[0]))),
        "by_launch_year": dict(sorted(by_launch_year.items(), key=lambda kv: kv[0])),
        "top_owning_teams": [
            {"owning_team": team, "count": count}
            for team, count in by_team.most_common(TOP_TEAMS_LIMIT)
        ],
    }


def parse_args(argv: list[str]) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Summarize the sample application listings under examples/."
    )
    parser.add_argument(
        "--file",
        help="Summarize only this one file (name or path under examples/), "
        "instead of every *.jsonl file there.",
    )
    parser.add_argument(
        "--json",
        action="store_true",
        help="Print machine-readable JSON instead of formatted text.",
    )
    return parser.parse_args(argv)


def resolve_files(file_arg: str | None) -> list[Path]:
    if file_arg is None:
        return sorted(EXAMPLES_DIR.glob("*.jsonl"))

    candidate = Path(file_arg)
    path = candidate if candidate.is_absolute() else EXAMPLES_DIR / candidate.name
    if not path.is_file():
        raise SystemExit(f"error: no such file under examples/: {file_arg}")
    return [path]


def main(argv: list[str]) -> int:
    args = parse_args(argv)

    try:
        files = resolve_files(args.file)
    except SystemExit as exc:
        print(exc, file=sys.stderr)
        return 1

    if not files:
        print("error: no *.jsonl files found under examples/", file=sys.stderr)
        return 1

    per_file: list[tuple[str, dict[str, Any]]] = []
    for path in files:
        try:
            listings = load_listings(path)
        except ValueError as exc:
            print(f"error: {exc}", file=sys.stderr)
            return 1
        per_file.append((path.name, summarize(listings)))

    if args.json:
        output: dict[str, Any] = {"files": {name: summary for name, summary in per_file}}
        if len(per_file) > 1:
            output["combined"] = combine([summary for _, summary in per_file])
        print(json.dumps(output, indent=2))
        return 0

    for name, summary in per_file:
        print_summary(name, summary)

    if len(per_file) > 1:
        print_summary("all files combined", combine([summary for _, summary in per_file]))

    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))

